import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import Cursor from "./Cursor";
import {
  FaInstagram,
  FaYoutube,
  FaFacebookF,
  FaTwitter,
  FaTiktok
} from "react-icons/fa";

export default function LandingPage() {

  const socials = [
    { icon: FaInstagram, link: "https://instagram.com" },
    { icon: FaYoutube, link: "https://youtube.com" },
    { icon: FaFacebookF, link: "https://facebook.com" },
    { icon: FaTwitter, link: "https://x.com" },
    { icon: FaTiktok, link: "https://tiktok.com" },
  ];

  const eventDate = new Date("2026-06-30T18:00:00").getTime();

  const [timeLeft, setTimeLeft] = useState({
    days: "00",
    hours: "00",
    minutes: "00",
    seconds: "00",
  });

  function getTimeRemaining() {
    const now = new Date().getTime();
    const distance = eventDate - now;

    if (distance <= 0) {
      return {
        days: "00",
        hours: "00",
        minutes: "00",
        seconds: "00",
      };
    }

    return {
      days: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, "0"),
      hours: String(Math.floor((distance / (1000 * 60 * 60)) % 24)).padStart(2, "0"),
      minutes: String(Math.floor((distance / (1000 * 60)) % 60)).padStart(2, "0"),
      seconds: String(Math.floor((distance / 1000) % 60)).padStart(2, "0"),
    };
  }

  useEffect(() => {
    const updateTime = () => {
      setTimeLeft(getTimeRemaining());
    };

    updateTime();
    const timer = setInterval(updateTime, 1000);
    return () => clearInterval(timer);
  }, []);

  const [menuOpen, setMenuOpen] = useState(false);

  const handleScroll = (id) => {
    let targetId = id;
    if (id === "fights") targetId = "about";
    if (id === "news") targetId = "sponsors";
    if (id === "contact") targetId = "sponsors";

    const section = document.getElementById(targetId);
    if (section) {
      section.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }
    setMenuOpen(false);
  };

  return (
    <>
      <Cursor />
      <div className="bg-black text-white font-[Inter] overflow-x-hidden w-full">
        {/* ================= NAVBAR ================= */}
        <nav className="fixed w-full z-50 bg-black/90 border-b border-neutral-900 backdrop-blur-sm">
          <div className="max-w-[1400px] mx-auto px-4 sm:px-6 md:px-8 lg:px-10 xl:px-12 2xl:px-16 h-14 sm:h-16 md:h-18 lg:h-20 flex items-center justify-between">
            <div className="flex items-center shrink-0">
              <img
                src="/gfc-logo.png"
                alt="GFC Logo"
                className="h-8 sm:h-9 md:h-10 lg:h-12 xl:h-14 2xl:h-16 w-auto object-contain"
              />
            </div>

            <ul className="hidden lg:flex gap-4 xl:gap-6 2xl:gap-8 text-[11px] xl:text-xs 2xl:text-sm uppercase tracking-wider font-semibold">
              {navItems.map((item) => (
                <li
                  key={item.id}
                  onClick={() => handleScroll(item.id)}
                  className="hover:text-red-500 transition cursor-pointer whitespace-nowrap"
                >
                  {item.name}
                </li>
              ))}
            </ul>

            <ul className="hidden md:flex lg:hidden gap-2 md:gap-3 text-[9px] md:text-[10px] uppercase tracking-wider font-semibold">
              {navItems.map((item) => (
                <li
                  key={item.id}
                  onClick={() => handleScroll(item.id)}
                  className="hover:text-red-500 transition cursor-pointer whitespace-nowrap"
                >
                  {item.name}
                </li>
              ))}
            </ul>

            <button
              onClick={() => setMenuOpen(!menuOpen)}
              className="md:hidden text-white text-2xl focus:outline-none p-2"
            >
              ☰
            </button>

            <button className="hidden sm:block bg-red-600 px-3 sm:px-4 md:px-5 py-1.5 sm:py-2 text-[10px] sm:text-xs md:text-sm font-semibold rounded-sm hover:bg-red-700 transition whitespace-nowrap">
              GET TICKETS
            </button>
          </div>

          {menuOpen && (
            <div className="md:hidden bg-black border-t border-neutral-800 flex flex-col items-center py-4 gap-3 text-sm uppercase max-h-[80vh] overflow-y-auto">
              {navItems.map((item) => (
                <div
                  key={item.id}
                  onClick={() => handleScroll(item.id)}
                  className="hover:text-red-500 cursor-pointer py-1"
                >
                  {item.name}
                </div>
              ))}
              <button className="bg-red-600 px-6 py-2 text-xs font-semibold mt-2 w-40 rounded-sm">
                GET TICKETS
              </button>
            </div>
          )}
        </nav>

        {/* ================= HERO SECTION - FIXED HEIGHT ================= */}
        <section
          id="home"
          className="relative flex items-center justify-center bg-black overflow-hidden"
          style={{
            height: "auto",
            minHeight: "600px",
            maxHeight: "900px",
          }}
        >
          {/* BACKGROUND IMAGE */}
          <div className="absolute inset-0 w-full h-full overflow-hidden">
            <div className="absolute right-0 top-1/2 -translate-y-1/2 w-full h-full flex justify-end">
              <img
                src="/fighter.png"
                alt="fighter"
                className="object-contain object-right h-full max-h-[85%] w-auto opacity-60 md:opacity-70"
                style={{
                  maxWidth: "55%",
                  minWidth: "280px",
                }}
              />
            </div>
          </div>

          {/* GRADIENT OVERLAY */}
          <div className="absolute inset-0 bg-gradient-to-r from-black via-black/80 to-transparent z-5" />

          {/* CONTENT */}
          <div className="relative z-10 w-full max-w-[1400px] mx-auto px-4 sm:px-6 md:px-8 lg:px-10 xl:px-12 2xl:px-16 py-12 sm:py-16 md:py-20 lg:py-24">
            <div className="w-full max-w-[90%] sm:max-w-[80%] md:max-w-[70%] lg:max-w-[60%] xl:max-w-[55%] 2xl:max-w-[50%]">
              <p className="text-red-500 text-xs sm:text-sm md:text-base lg:text-lg uppercase tracking-[2px] sm:tracking-[3px] md:tracking-[4px] mb-2 sm:mb-3 md:mb-4">
                GFC GLOBAL 1: ORIGIN
              </p>

              <h1 className="font-[Anton] italic uppercase tracking-[0.5px] leading-[1.05] sm:leading-[1.08] md:leading-[1.1] text-4xl sm:text-5xl md:text-6xl lg:text-7xl xl:text-8xl 2xl:text-9xl">
                <span className="block">FIGHTS.</span>
                <span className="block">STORIES.</span>
                <span className="block text-red-500">LEGENDS.</span>
              </h1>

              <p className="mt-3 sm:mt-4 md:mt-5 text-gray-300 text-sm sm:text-base md:text-lg lg:text-xl">
                India's Next Combat Sports Movement
              </p>

              <div className="flex flex-col sm:flex-row gap-3 sm:gap-4 md:gap-5 mt-5 sm:mt-6 md:mt-7 lg:mt-8">
                <button className="bg-red-600 px-5 sm:px-6 md:px-7 lg:px-8 py-2.5 sm:py-3 md:py-3.5 lg:py-4 text-xs sm:text-sm md:text-base font-semibold rounded-sm hover:bg-red-700 transition">
                  GET TICKETS
                </button>
                <button className="border border-white px-5 sm:px-6 md:px-7 lg:px-8 py-2.5 sm:py-3 md:py-3.5 lg:py-4 text-xs sm:text-sm md:text-base rounded-sm hover:bg-white/10 transition">
                  ▶ WATCH TRAILER
                </button>
              </div>
            </div>
          </div>
        </section>

        {/* ================= FEATURES SECTION ================= */}
        <section id="about" className="border-t border-neutral-900 bg-black">
